import os

def safe_path(base, name):
    full = os.path.normpath(os.path.join(base, name))
    if not full.startswith(base.rstrip("/") + "/"):
        raise ValueError("outside base")
    return full

alt:
import os

def safe_path(base, name):
    full = os.path.normpath(os.path.join(base, name))
    if os.path.commonpath([base, full]) != base:
        raise ValueError("outside base")
    return full
